insert into practice_exercises (id, subject_name, level, title, source) values
  ('9156a022-4b6f-416b-99e2-2b43ac8411c9', $$Natuurkunde$$, $$HAVO$$, $$Kunstmatige meteoroïden$$, $$HAVO Natuurkunde 2024-II$$),
  ('22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$Natuurkunde$$, $$HAVO$$, $$Knakworstenverwarmer$$, $$HAVO Natuurkunde 2024-II$$),
  ('762d2bed-3ee2-40b8-8d44-856d885467a4', $$Natuurkunde$$, $$HAVO$$, $$Boombrommer$$, $$HAVO Natuurkunde 2024-II$$),
  ('86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$Natuurkunde$$, $$HAVO$$, $$Wiebelgenerator$$, $$HAVO Natuurkunde 2024-II$$),
  ('e68fa677-0eee-4824-a86e-cc53996f5d17', $$Natuurkunde$$, $$HAVO$$, $$Gebitsfoto$$, $$HAVO Natuurkunde 2024-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('3ce9a21d-d12f-4c94-8024-0be5ca78c125', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$figuur 1 — lichtspoor van een meteoroïde aan de sterrenhemel$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context1.png$$, 498, $$Meteoroïden zijn objecten uit de ruimte die lichtflitsen veroorzaken bij het binnendringen en doorkruisen van de atmosfeer van de aarde. Deze lichtflitsen zijn als lichtsporen aan de hemel te zien. Zie figuur 1.

figuur 1: nachtelijke foto van een sterrenhemel boven een bosrijk meer, met een helder lichtspoor van een meteoroïde schuin door de Melkweg.$$, 'inline'),
  ('57b15749-22f8-41a1-a69a-6f75e4081c0b', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$snelheid meteoroïden tussen 3,5·10⁴ en 2,5·10⁵ kmh⁻¹; spoor 1,22 s zichtbaar$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context2.png$$, 498, $$Meteoroïden komen de aardatmosfeer binnen met een snelheid tussen 3,5·10⁴ kmh⁻¹ en 2,5·10⁵ kmh⁻¹. De meteoroïde in figuur 1 was gedurende 1,22 s zichtbaar aan de hemel.$$, 'inline'),
  ('f2739e4a-e2e6-4203-8433-6a69db9dcb8a', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$kunstmatige meteoroïden: satelliet lanceert metalen bolletjes die door luchtwrijving oplichten$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context3.png$$, 498, $$Het waarnemen van een meteoroïde is een toevalstreffer. Daarom ontwikkelt een Japans bedrijf kunstmatige meteoroïden om deze op afroep als kosmisch vuurwerk in te zetten. Het bedrijf heeft een satelliet ontworpen die vanuit de ruimte metalen bolletjes kan lanceren richting de aarde. Deze bolletjes komen de aardatmosfeer binnen op hoge snelheid. Door de luchtwrijving bereiken de bolletjes een zeer hoge temperatuur waardoor ze gedurende langere tijd helder licht uitzenden.$$, 'inline'),
  ('6d2b8819-0cc4-4501-8051-6dcd56c38571', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$testopstelling: golflengte met de hoogste intensiteit is 940 nm$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context4.png$$, 498, $$Het bedrijf heeft de bolletjes getest in een testopstelling waar ze de vlucht door de aardatmosfeer nabootsen met een luchtstroom. De temperatuur van de bolletjes wordt bepaald door de golflengte van de straling met de hoogste intensiteit te meten. Deze is 940 nm.$$, 'inline'),
  ('9815a19a-2e5a-4954-80d3-14621f20ce73', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$satelliet in een cirkelbaan op 4,0·10² km hoogte$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context5.png$$, 498, $$De satelliet van het bedrijf draait op 4,0·10² km hoogte boven het aardoppervlak in een cirkelbaan.$$, 'inline'),
  ('e31afb6d-806f-4a78-8e22-810cd35b7dbf', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$verklaringen van Max en Lara waarom een bolletje niet in de cirkelbaan blijft$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context6.png$$, 498, $$De bolletjes beginnen hun val vanuit de satelliet richting aarde.
Max en Lara hebben ieder een verklaring waarom een bolletje niet in een cirkelbaan om de aarde blijft draaien, maar naar de aarde toe valt:
− Volgens Max valt een bolletje naar de aarde omdat het een lagere snelheid heeft dan de benodigde baansnelheid.
− Volgens Lara valt een bolletje naar de aarde omdat de gravitatiekracht groter is dan de middelpuntzoekende kracht die nodig is voor de cirkelbaan.$$, 'inline'),
  ('fbd6af66-0e51-4bda-aa83-4829b59fdef9', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$val van de bolletjes: beginsnelheid 7,5·10³ ms⁻¹, atmosfeer op 1,0·10² km, vergelijking met 3,5·10⁴ kmh⁻¹$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context7.png$$, 498, $$De bolletjes beginnen hun val richting aarde met een beginsnelheid van 7,5·10³ ms⁻¹.
De valversnelling mag tijdens de hele val gelijkgesteld worden aan de valversnelling op aarde. Op een hoogte van 1,0·10² km komen de bolletjes de aardatmosfeer binnen.
De snelheid van de bolletjes is dan lager dan de snelheid van 3,5·10⁴ kmh⁻¹ van een echte meteoroïde.$$, 'inline'),
  ('aaab0e60-ac5b-4c3a-a951-22c36f77107c', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$figuur 2 — kegel met hoogte h = 1,0·10² km en tophoek α van 77 graden$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context8.png$$, 498, $$De kunstmatige meteoroïden lichten op als ze de atmosfeer op h = 1,0·10² km boven het aardoppervlak binnendringen. Ze zijn op dat moment overal vanaf het aardoppervlak waarneembaar binnen een cirkelvormig gebied dat de basis is van een kegel met hoogte h en een tophoek α van 77 graden. Zie schematisch en niet op schaal in figuur 2.

figuur 2: satellietfoto van de aarde vanuit de ruimte met daaroverheen een schematisch getekende kegel; de top van de kegel ligt bij het lichtspoor van de meteoroïde, met de tophoek α, de hoogte h en de diameter d van het cirkelvormige grondvlak aangegeven.$$, 'inline'),
  ('5dbdfaa8-b4a9-475c-bdc3-e60edf792efe', '9156a022-4b6f-416b-99e2-2b43ac8411c9', $$figuur 3 — vier gebieden I t/m IV met orde van grootte d~10⁰ tot d~10³ km$$, $$natuurkunde-havo-2024-ii-kunstmatige-meteoroiden-context9.png$$, 498, $$In figuur 3 zijn vier gebieden (I, II, III en IV) met bijbehorende orde van grootte weergegeven.

figuur 3: vier kaartjes naast elkaar met bijbehorende orde van grootte: I op loopafstand d~10⁰ km, II op fietsafstand d~10¹ km, III op auto-afstand d~10² km en IV op vliegafstand d~10³ km.$$, 'inline'),
  ('fccb59da-cbe3-41c2-a03c-aaed2c912b9c', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$figuur 1 — foto van de schakeling met knakworst, spanningsbron en de meters I en II$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context1.png$$, 498, $$Lieke onderzoekt of het mogelijk is om een knakworst te verwarmen door er een elektrische stroom doorheen te sturen.
Hiervoor prikt ze twee aansluitpunten in een knakworst en bouwt ze de schakeling van figuur 1.

figuur 1: foto van de opstelling met links een regelbare spanningsbron, in het midden een knakworst op een wit plaatje met twee draden erin geprikt, en twee multimeters die met snoeren in de schakeling zijn opgenomen: meter I bovenaan en meter II rechts.$$, 'inline'),
  ('23fb0dd9-6180-4ec8-9b0c-ec4791e4191c', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$meters I en II: de ene is spanningsmeter, de andere stroommeter$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context2.png$$, 498, $$In de schakeling van figuur 1 zijn twee meters (I en II) opgenomen. Eentje werkt als spanningsmeter, de andere als stroommeter.$$, 'inline'),
  ('c018601d-c719-4ef0-88ef-c5f046030309', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$figuur 2 — (I,U)-diagram van de knakworst bij metingen in zeer korte tijd$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context3.png$$, 498, $$Lieke meet de stroom I door de knakworst bij verschillende spanningen U. Ze voert de metingen in zeer korte tijd uit, om de knakworst tijdens deze metingen nog niet te laten opwarmen.

Van haar metingen maakt ze een (I,U)-diagram. Zie figuur 2.

figuur 2: (I,U)-diagram met I (A) van 0 tot 0,14 op de verticale as en U (V) van 0 tot 35 op de horizontale as; de meetpunten liggen op een vrijwel rechte lijn door de oorsprong, die bij U = 35 V een stroomsterkte van ongeveer 0,13 A bereikt.$$, 'inline'),
  ('f10ce4f0-a25e-4b1e-a20c-c3cc86d43d2d', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$soortelijke weerstand zout water 0,24 Ωm; knakworst diameter 15 mm en lengte 8,0 cm$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context4.png$$, 498, $$Op het potje van de knakworsten staat dat er zout in zit. Lieke vraagt zich af of de soortelijke weerstand van de knakworst hetzelfde is als die van zout water. Op internet vindt ze dat de soortelijke weerstand van zout water gelijk is aan 0,24 Ωm.
De knakworst heeft een diameter van 15 mm en de lengte van de knakworst tussen de aansluitpunten van de draden is 8,0 cm.$$, 'inline'),
  ('f617098e-babc-428c-a123-3c09b28cc71a', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$figuur 3 — (I,t)-diagram tijdens het opwarmen bij constante spanning$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context5.png$$, 498, $$Vervolgens zet Lieke een constante spanning over de knakworst. Nu laat ze de knakworst wel opwarmen. Het valt Lieke op dat de stroomsterkte niet constant blijft tijdens het verwarmen. Ze maakt daarom een (I,t)-diagram. Zie figuur 3.

figuur 3: (I,t)-diagram met I (A) van 0 tot 0,16 op de verticale as en t (min) van 0 tot 9 op de horizontale as; de stroomsterkte begint bij ongeveer 0,11 A en stijgt steeds langzamer tot ongeveer 0,138 A na 9 minuten.$$, 'inline'),
  ('8fb234c9-2fa4-4295-b8f8-d4b7770166ec', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$opwarmen van 22 °C naar 60 °C in 14 min; P = 3,9 W; m = 20 g; c = 3,0·10³ J kg⁻¹ K⁻¹$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context6.png$$, 498, $$Lieke laat de knakworst in 14 minuten opwarmen van een temperatuur van 22 °C tot een temperatuur van 60 °C. Ze vraagt zich af wat het rendement is van haar opstelling tijdens het opwarmen van de knakworst. Het gemiddelde elektrische vermogen tijdens het opwarmen is 3,9 W. De massa van de knakworst is 20 g. Ze vindt op internet dat vlees een soortelijke warmte heeft van 3,0·10³ J kg⁻¹ K⁻¹.$$, 'inline'),
  ('5c3dec88-d24e-4bf1-ac5e-2cdcb0ad6b3f', '22a4faa7-4eb1-41e5-8559-455a6c74eb5a', $$meerdere knakworsten tegelijk; spanningsbron levert maximaal 35 V en 5,0 A$$, $$natuurkunde-havo-2024-ii-knakworstenverwarmer-context7.png$$, 498, $$Lieke wil nu met haar opstelling, in dezelfde tijd als bij één knakworst, meerdere knakworsten tegelijk opwarmen tot een temperatuur van 60 °C.
Op de spanningsbron staat vermeld dat deze een maximale spanning van 35 V kan leveren en een maximale stroomsterkte van 5,0 A.$$, 'inline'),
  ('7edfd2b6-3af3-4615-8d30-46b3f8bc8f8a', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$figuur 1 en 2 — palmbomen en een boombrommer die langs de stam omhoog rijdt$$, $$natuurkunde-havo-2024-ii-boombrommer-context1.png$$, 498, $$Betelnoten groeien in de toppen van palmbomen. De stammen van die bomen zijn hoog en kaarsrecht. Zie figuur 1. Boeren beklimmen deze bomen om de noten te plukken. Een uitvinder heeft een boombrommer gemaakt om langs een stam omhoog naar de top te kunnen ‘rijden’. Zie figuur 2.

figuur 1: foto van onderaf van een dicht bos met hoge, kaarsrechte palmbomen.
figuur 2: foto van een man die op een boombrommer zit die met wielen om een palmstam klemt en zo langs de stam omhoog rijdt.$$, 'inline'),
  ('6bdf2d66-c699-48b3-be77-ea684cc8e18b', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$werking boombrommer: benzinemotor omhoog met constante snelheid, rem om stil te hangen en af te dalen$$, $$natuurkunde-havo-2024-ii-boombrommer-context2.png$$, 498, $$De brommer klemt met wielen om de stam.
Een benzinemotor kan de brommer met constante snelheid langs de stam naar boven laten rijden.
De boombrommer is uitgerust met een rem. Deze rem zorgt voor een grote remkracht op de brommer, waardoor die stil kan hangen aan de stam. De boombrommer kan vanuit stilstand weer afdalen langs de stam door de remkracht te verkleinen.$$, 'inline'),
  ('1ca54c94-d67e-40f3-a90c-fe255c402769', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$figuur 3 — (h,t)-diagram van de testrit van de boombrommer$$, $$natuurkunde-havo-2024-ii-boombrommer-context3.png$$, 498, $$De uitvinder heeft een testrit gemaakt om de boombrommer te demonstreren. Van deze rit is een (h,t)-diagram gemaakt. Zie figuur 3.

figuur 3: (h,t)-diagram met h (m) van 0 tot 9 op de verticale as en t (s) van 0 tot 45 op de horizontale as; de hoogte blijft eerst ongeveer 0,9 m, stijgt dan snel naar ongeveer 4,2 m, blijft daar tussen ongeveer 5 en 8 s constant, daalt naar ongeveer 1,7 m tussen ongeveer 12 en 17 s, stijgt daarna rechtlijnig naar ongeveer 7,4 m rond 29 tot 31 s en daalt vervolgens rechtlijnig naar ongeveer 1 m bij t = 45 s.$$, 'inline'),
  ('e922e779-0424-4d1c-9451-b7e0c9cf9cbf', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$verwijzing naar de tabel op de uitwerkbijlage$$, $$natuurkunde-havo-2024-ii-boombrommer-context4.png$$, 498, $$Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('87373c39-88fa-4eab-ac83-b9e8bccda110', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$uitwerkbijlage vraag 12 — tabel met de tijdstippen 7, 23 en 36 s en drie beweringen over arbeid$$, $$natuurkunde-havo-2024-ii-boombrommer-uitwerkbijlage-vraag12.png$$, 498, $$Uitwerkbijlage vraag 12: ‘Geef in de tabel met een kruisje per tijdstip aan welke bewering juist is.’, met daaronder een tabel met de kolommen ‘tijdstip (s):’, ‘de motorkracht verricht arbeid’, ‘de remkracht verricht arbeid’ en ‘er wordt geen arbeid verricht’ en de rijen 7, 23 en 36, met lege vakjes om een kruisje in te zetten.$$, 'uitwerkbijlage'),
  ('52fc1b58-4824-4675-8965-9657e87cf336', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$figuur 3 staat ook op de uitwerkbijlage$$, $$natuurkunde-havo-2024-ii-boombrommer-context5.png$$, 498, $$Figuur 3 staat ook op de uitwerkbijlage.$$, 'inline'),
  ('e23e5c4e-f2fa-4d32-87b2-da0d0a3b751c', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$uitwerkbijlage vraag 13 — herhaling van figuur 3 met invulregels bij Antwoord$$, $$natuurkunde-havo-2024-ii-boombrommer-uitwerkbijlage-vraag13.png$$, 498, $$Uitwerkbijlage vraag 13: dezelfde (h,t)-grafiek als figuur 3 (h in m van 0 tot 9, t in s van 0 tot 45), gevolgd door invulregels bij ‘Antwoord:’ waarop de leerling de bepaling van de maximale snelheid kan toelichten.$$, 'uitwerkbijlage'),
  ('865f6c36-9673-4367-970d-f692ffd94714', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$figuur 4 — stil hangende boombrommer met draaipunt D, steunwiel S, arm rFn en Fz; massa 104 kg$$, $$natuurkunde-havo-2024-ii-boombrommer-context6.png$$, 498, $$In figuur 4 is de situatie van een stil hangende boombrommer schematisch en op schaal weergegeven. Bij het ontwerp is handig gebruikgemaakt van de hefboomwet. De brommer heeft een draaipunt D. De boom oefent op steunwiel S alleen een normaalkracht Fn uit. Door de arm rFn ontstaat er een moment M. Dit is in evenwicht met het moment van de zwaartekracht Fz op de uitvinder en brommer samen. De uitvinder hangt stil. De massa van de uitvinder en boombrommer samen is 104 kg.

figuur 4: schematische tekening op schaal van een uitvinder die op de boombrommer zit die met wielen tegen een boomstam klemt; het draaipunt D en het steunwiel S zijn aangegeven, de arm rFn is als verticale lijn tussen S en D getekend en de zwaartekracht Fz is als neerwaartse pijl vanuit het zwaartepunt getekend.$$, 'inline'),
  ('5e6173ba-98d1-465a-83be-92d47ae1396b', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$figuur 4 staat ook op de uitwerkbijlage$$, $$natuurkunde-havo-2024-ii-boombrommer-context7.png$$, 498, $$Figuur 4 staat ook op de uitwerkbijlage.$$, 'inline'),
  ('197ad445-0a9b-4afe-aebc-d0cb85abc919', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$uitwerkbijlage vraag 14 — figuur 4 om de arm van de zwaartekracht in te tekenen$$, $$natuurkunde-havo-2024-ii-boombrommer-uitwerkbijlage-vraag14.png$$, 498, $$Uitwerkbijlage vraag 14: dezelfde schematische tekening op schaal als figuur 4 (uitvinder op de boombrommer tegen de boomstam, met draaipunt D, steunwiel S, de arm rFn en de zwaartekracht Fz), waarin de leerling de arm van de zwaartekracht moet tekenen, gevolgd door invulregels bij ‘Bepaling:’.$$, 'uitwerkbijlage'),
  ('1e561bc4-bb52-415d-920f-f6868d5027c1', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$Fn zo klein mogelijk houden door de afstand SD te verkleinen$$, $$natuurkunde-havo-2024-ii-boombrommer-context8.png$$, 498, $$De uitvinder wil dat de boom niet wordt beschadigd. Daarom wil hij Fn zo klein mogelijk houden. In het ontwerp kan hij de afstand SD kleiner maken.$$, 'inline'),
  ('1abeaab4-99fd-47b2-afc3-4a7a65089601', '762d2bed-3ee2-40b8-8d44-856d885467a4', $$bewering: 135 bomen van elk 30 m met 1,5 liter benzine; rendement motor 18%$$, $$natuurkunde-havo-2024-ii-boombrommer-context9.png$$, 498, $$De uitvinder beweert dat hij 135 bomen van elk 30 m hoog kan beklimmen met 1,5 liter benzine. Het rendement van de motor die in de boombrommer zit, is 18%.$$, 'inline'),
  ('88753317-06ef-4f90-8cc3-e8dc372a4d7b', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$figuur 1 — prototype met 12,5 m lange paal die in de grondtoon trilt$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-context1.png$$, 498, $$Er wordt onderzoek gedaan naar een nieuwe methode om windenergie om te zetten in elektrische energie. Bij een bepaalde experimentele methode wordt een lange paal gebruikt waarin staande golven ontstaan als de paal in de wind staat. De wiebelende paal wekt elektriciteit op en wordt dan ook ‘wiebelgenerator’ genoemd. Voor een test is een prototype van een wiebelgenerator gemaakt met een 12,5 m lange paal. Zie figuur 1. In deze figuur is schematisch weergegeven hoe de paal in de grondtoon trilt.

figuur 1: schematische tekening van een 12,5 m lange verticale paal die aan de onderkant is ingeklemd; met stippellijnen zijn de uiterste standen van de trillende paal weergegeven, met de grootste uitwijking aan de bovenkant.$$, 'inline'),
  ('7f936e5e-b2c4-43c6-96c8-b036d7e73c30', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$uitwerkbijlage vraag 17 — tekening van de paal om knopen K en buiken B in te tekenen$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-uitwerkbijlage-vraag17.png$$, 498, $$Uitwerkbijlage vraag 17: ‘Geef het patroon van knopen (K) en buiken (B) voor de eerste boventoon van de paal.’, met daaronder een tekening van de rechte, aan de onderkant ingeklemde paal waarin de leerling het patroon moet aangeven.$$, 'uitwerkbijlage'),
  ('005ce3f8-a0dd-492b-9ada-1e4d111029ce', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$figuur 2 — (u,t)-diagram van de paal die in de grondtoon trilt$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-context2.png$$, 498, $$De frequentie waarmee de paal gaat trillen, is afhankelijk van de voortplantingssnelheid van de golven in de paal. Om deze snelheid te bepalen, wordt tijdens een test de paal aan het trillen gebracht in de grondtoon. Zie figuur 1. Van deze trilling wordt een (u,t)-diagram gemaakt. Zie figuur 2.

figuur 2: (u,t)-diagram met u (m) van −0,4 tot 0,4 op de verticale as en t (s) van 0 tot 10 op de horizontale as; de trilling begint bij t = 0 met een kleine uitwijking en groeit binnen enkele seconden uit tot een vrijwel constante amplitude van ongeveer 0,3 m.$$, 'inline'),
  ('06c70b0e-c7b2-42b4-9536-181f49046012', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$wervelfrequentie fw moet gelijk zijn aan de eigenfrequentie f0; veerconstante regelbaar; paal als massa-veer-systeem$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-context3.png$$, 498, $$Als gevolg van de wind ontstaan er rond de paal wervelingen met een bepaalde frequentie fw. Voor een zo groot mogelijke opbrengst van de wiebelgenerator moet fw gelijk zijn aan de eigenfrequentie f0 van de grondtoon. De frequentie fw is niet constant, maar afhankelijk van de windsnelheid. De eigenfrequentie f0 moet dus aangepast kunnen worden tijdens het veranderen van de windsnelheid. De onderzoekers denken dit te kunnen doen met een technische oplossing waarmee de veerconstante van de paal kan worden verhoogd of verlaagd.
De paal is te modelleren als een massa-veer-systeem.
Op de uitwerkbijlage staan hierover twee zinnen.$$, 'inline'),
  ('a721fc0e-55d1-45d5-9974-64fc03294c16', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$uitwerkbijlage vraag 19 — twee zinnen over trillingstijd en veerconstante om te omcirkelen$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-uitwerkbijlage-vraag19.png$$, 498, $$Uitwerkbijlage vraag 19: ‘Omcirkel in iedere zin het juiste alternatief.’, met de zinnen ‘Wanneer de windsnelheid en dus de frequentie fw afneemt, moet de trillingstijd van de paal toenemen / afnemen.’ en ‘De veerconstante moet dan verhoogd / verlaagd worden.’$$, 'uitwerkbijlage'),
  ('3d7e8d50-b333-4066-b9b9-5e2a42e2f05f', '86ec7b9d-7952-4ef8-9ec7-f51783e24ed6', $$nuttig vermogen 100 W bij v = 12 m s⁻¹; Pwind = 0,30·ρ·A·v³ (1); A = 1,2 m²; windturbine 35%$$, $$natuurkunde-havo-2024-ii-wiebelgenerator-context4.png$$, 498, $$Met behulp van het model wordt berekend dat het nuttige vermogen van de wiebelgenerator bij een bepaalde lengte van de paal gelijk is aan 100 W. Men wil het rendement van de wiebelgenerator bij een windsnelheid van 12 m s⁻¹ vergelijken met het rendement van een reguliere windturbine onder dezelfde omstandigheden.
Voor het vermogen dat de wind overdraagt op de wiebelgenerator geldt:

Pwind = 0,30 · ρ · A · v³   (1)

Hierin is:
− Pwind het overgedragen vermogen;
− ρ de dichtheid van lucht;
− A het frontaal oppervlak van de wiebelende paal;
− v de windsnelheid.

Het frontaal oppervlak voor de paal in het model wordt gesteld op 1,2 m². Een reguliere windturbine heeft onder dezelfde omstandigheden een rendement van 35%.$$, 'inline'),
  ('95aef961-0115-44fd-ab4e-e1b82cead342', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$figuur 1 — röntgenapparaat met draaibare scanner, zender en ontvanger$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context1.png$$, 498, $$Om het gebit goed te kunnen beoordelen, maakt de tandarts röntgenscans. Voor het maken van een röntgenscan kan de tandarts een röntgenapparaat met een draaibare scanner gebruiken waarmee die een foto van het volledige gebit kan maken. In korte tijd draait de scanner rondom het hoofd van de patiënt. Zie figuur 1.

figuur 1: tekening van een patiënt die in een röntgenapparaat staat; de draaibare scanner rond het hoofd is aangewezen, met daarop de ontvanger aan de ene kant en de zender aan de andere kant.$$, 'inline'),
  ('2184d069-b626-416b-b003-b4951b36c95b', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$figuur 2 — schakeling van de röntgenbuis met instelbare spanning U en trefplaatje$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context2.png$$, 498, $$De röntgenstraling wordt opgewekt in een zogenaamde röntgenbuis. Dit gebeurt door in de röntgenbuis een trefplaatje te beschieten met elektronen. De snelheid van de elektronen kan verhoogd worden door het verhogen van een instelbare spanning U over de röntgenbuis. Zie figuur 2.

figuur 2: schakelschema met een instelbare spanningsbron, een spanningsmeter (V) daaraan parallel en een stroommeter (A) in de hoofdkring; in de kring is de röntgenbuis met een stippellijn omkaderd, met daarin elektronen (e⁻) die naar een trefplaatje versnellen waaruit röntgenfotonen ontstaan.$$, 'inline'),
  ('d9cb0daa-2987-47be-b143-a9c9d7d40751', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$golflengte van fotonen voor gebitsfoto’s tussen 0,01 nm en 10 nm; fotonenergie 85 keV$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context3.png$$, 498, $$Snellere elektronen leveren fotonen op met een hogere foton-energie en dus een kleinere golflengte. De golflengte van fotonen die voor gebitsfoto’s worden gebruikt, ligt tussen de 0,01 nm en 10 nm. De spanning U is zo ingesteld dat de fotonenergie 85 keV is.$$, 'inline'),
  ('223e1048-f83c-4640-aae7-2e95966d949c', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$stroomsterkte elektronen 6,0 mA; 1 op de 100 elektronen maakt een foton vrij$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context4.png$$, 498, $$Hoeveel fotonen er per seconde ontstaan, wordt onder andere bepaald door de stroomsterkte I van de elektronen in de röntgenbuis. Deze stroomsterkte is 6,0 mA. Slechts 1 op de 100 elektronen uit deze stroom maakt echt een foton vrij in het trefplaatje.$$, 'inline'),
  ('efdb5152-8df0-4487-b17a-fc3f07a803a4', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$proefscan met pop als dosimeter: 2,6·10⁻⁴ W, 16,7 s, bestraalde massa 1,5 kg$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context5.png$$, 498, $$Om de stralingsdosis goed te kunnen instellen, worden proefmetingen in de scanner gedaan met een pop die werkt als een dosimeter.
De pop ontvangt tijdens een proefscan een stralingsvermogen van 2,6·10⁻⁴ W. Het maken van de totale scan duurt 16,7 s. De massa van het bestraalde materiaal is 1,5 kg.$$, 'inline'),
  ('2317007d-55f7-4f25-bdf0-8996ddc261a3', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$figuur 3 — röntgenscan van het gebit met implantaat; figuur 4 — bovenaanzicht zender, kiezen en ontvanger$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context6.png$$, 498, $$In figuur 3 is de scan te zien zoals een tandarts die heeft gemaakt van een patiënt. Eén van de kiezen van de patiënt is vervangen door een implantaat van metaal. In de vergroting zijn een originele kies en het implantaat zichtbaar. De kies en het implantaat hebben dezelfde dikte. Zie het schematische bovenaanzicht in figuur 4.

figuur 3: röntgenscan van een volledig gebit met een uitvergroting van het gebied rond het implantaat; in de vergroting zijn het zachte weefsel, een originele kies en het tandheelkundig implantaat aangewezen. Het implantaat is fel wit op de scan.
figuur 4: schematisch bovenaanzicht met links een blok ‘zender’ en rechts een blok ‘ontvanger’; daartussen liggen de kiezen, waarvan er één als ‘originele kies’ (lichtgrijs) en één als ‘implantaat’ (donkergrijs) is aangeduid.$$, 'inline'),
  ('eeeef796-3ccc-4eaf-b94c-0518e1aef719', 'e68fa677-0eee-4824-a86e-cc53996f5d17', $$donkere gebieden op de scan betekenen meer gemeten straling$$, $$natuurkunde-havo-2024-ii-gebitsfoto-context7.png$$, 498, $$De donkere gebieden op de scan in figuur 3 geven aan dat er op die plaatsen meer straling door de ontvanger gemeten is.$$, 'inline');

