  ('dd816c0b-cf99-4fc6-9941-d54bdc28b443', '762d2bed-3ee2-40b8-8d44-856d885467a4', 13,
   $$[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]$$::jsonb,
