   $$natuurkunde-havo-2024-ii-boombrommer-vraag14.png$$, 498, $$4p 14 Voer de volgende opdrachten uit:
− Teken de arm van de zwaartekracht.
− Bepaal met behulp van de hefboomwet de grootte van de normaalkracht Fn op steunwiel S. Noteer je antwoord in twee significante cijfers.$$, array['865f6c36-9673-4367-970d-f692ffd94714','5e6173ba-98d1-465a-83be-92d47ae1396b','197ad445-0a9b-4afe-aebc-d0cb85abc919']::uuid[]),
  ('21139b7c-7883-40f4-8ea2-0cf6a5747291', '762d2bed-3ee2-40b8-8d44-856d885467a4', 15,
   $$[{"domain": "Beweging en energie", "subdomain": "Kracht en beweging"}]$$::jsonb,
