   $$natuurkunde-havo-2024-ii-boombrommer-vraag15.png$$, 498, $$3p 15 Leg uit of Fn groter wordt, kleiner wordt of gelijk blijft door een kleinere afstand SD.$$, array['865f6c36-9673-4367-970d-f692ffd94714','1e561bc4-bb52-415d-920f-f6868d5027c1']::uuid[]),
  ('968d4dc5-5863-4e9d-988e-ceea716fd63f', '762d2bed-3ee2-40b8-8d44-856d885467a4', 16,
